def counts(s):
    out={}
    for c in s: out[c]=out.get(c,0)+1
    return out

def palindrome(s):
    t="".join(c.lower() for c in s if c.isalnum())
    return t==t[::-1]

def totals(rows):
    out={}
    for r in rows: out[r["category"]]=out.get(r["category"],0)+r["amount"]
    return out

def common_prefix(xs):
    if not xs: return ""
    p=xs[0]
    for s in xs[1:]:
        while not s.startswith(p): p=p[:-1]
    return p

def latest(rows):
    out={}
    for r in rows:
        k,t=r["id"],r["time"]
        out[k]=max(out.get(k,t),t)
    return out

def merge_intervals(xs):
    out=[]
    for a,b in sorted(xs):
        if out and a<=out[-1][1]: out[-1][1]=max(out[-1][1],b)
        else: out.append([a,b])
    return out

def balanced(s):
    stack=[]
    pairs={")":"(","]":"[","}":"{"}
    for c in s:
        if c in "([{": stack.append(c)
        elif c in pairs:
            if not stack or stack.pop()!=pairs[c]: return False
    return not stack

def inventory(rows):
    out={}
    for r in rows: out[r["sku"]]=out.get(r["sku"],0)+r["qty"]
    return {k:v for k,v in out.items() if v!=0}

def window_max(xs,k):
    if k<1 or k>len(xs): return []
    return [max(xs[i:i+k]) for i in range(len(xs)-k+1)]

def rle(s):
    out=[]
    for c in s:
        if out and out[-1][0]==c: out[-1][1]+=1
        else: out.append([c,1])
    return out
